class AsyncExtension{getInfo(){return{id:"asyncexample",name:"Async Blocks",blocks:[{opcode:"wait",text:"wait [TIME] seconds",blockType:Scratch.BlockType.COMMAND,arguments:{TIME:{type:Scratch.ArgumentType.NUMBER,defaultValue:1}}},{opcode:"fetch",text:"fetch [URL]",blockType:Scratch.BlockType.REPORTER,arguments:{URL:{type:Scratch.ArgumentType.STRING,defaultValue:"https://extensions.turbowarp.org/hello.txt"}}}]}}wait(e){return new Promise((t,c)=>{const n=1e3*e.TIME;setTimeout(()=>{t()},n)})}fetch(e){return fetch(e.URL).then(e=>e.text()).catch(e=>(console.error(e),"Uh oh! Something went wrong."))}}Scratch.extensions.register(new AsyncExtension);